test('a restored console keeps history readable and drafts intact while blocking held command and retry handlers',async()=>{
 const app=await consoleApp({recovery:hold()});await app.select(ids.bidding);await app.load(ids.bidding,{recovery:hold(),jobs:[{id:'dead-job',status:'dead',attempts:3,error:'Fictional old worker failure'}],casework:{held:true,currentRevision:2,plans:[],contacts:{contacts:[],unknowns:[]},changes:{links:[],withdrawals:[],items:[],groups:[],interpretation:''},qa:[]}});assert.equal(app.$('notice').textContent,'','The complete held fixture must render before testing its action guards');assert.equal(app.$('recovery-hold').hidden,false);assert.match(app.$('recovery-hold-message').textContent,/fixture-console-restore/);assert.equal(app.$('incident-teams-controls').disabled,true);assert.equal(app.$('rollback-request').disabled,true);assert.equal(app.$('casework-plan').disabled,true);assert.equal(app.$('retry-work').querySelector('button').disabled,true);assert.equal(app.$('question').querySelector('button').disabled,false);app.$('teams-text').value='brief';app.$('retry-reason').value='Retained worker failure';await app.submit('teams');await app.submit('retry-work');await app.$('teams-join').onclick();await app.$('casework-plan').onclick();assert.equal(app.requests.filter(row=>row.method==='POST').length,0);assert.equal(app.$('teams-text').value,'brief');assert.equal(app.$('retry-reason').value,'Retained worker failure');assert.match(app.$('notice').textContent,/restore hold/i);assert.equal(app.$('conversation').hidden,false);
});
