test('a lost question response reuses its request identity, while an acknowledged repeat is a new explicit question',async()=>{
 const app=await consoleApp();await app.select(ids.bidding);await app.loadCurrent(ids.bidding);const text='Compare the accepted bid ledger and exact source';app.$('question-text').value=text;let submitted=app.submit('question');await flush();const first=app.requests.find(row=>row.method==='POST');assert.match(first.body.requestId,/^[a-f0-9-]{36}$/);await app.fail(first);await submitted;assert.match(app.$('notice').textContent,/retry ID stays in this open tab/);assert.equal(app.$('question-text').value,text);submitted=app.submit('question');await flush();const retry=app.requests.filter(row=>row.method==='POST').at(-1);assert.equal(retry.path,'/api/incidents/'+ids.bidding+'/question-requests');assert.equal(retry.body.requestId,first.body.requestId);await app.complete(retry,{duplicate:true,queued:0});await app.loadCurrent(ids.bidding);await submitted;assert.match(app.$('notice').textContent,/already saved/);assert.equal(app.$('question-text').value,'');app.$('question-text').value=text;submitted=app.submit('question');await flush();const intentional=app.requests.filter(row=>row.method==='POST').at(-1);assert.notEqual(intentional.body.requestId,first.body.requestId);await app.complete(intentional);await app.loadCurrent(ids.bidding);await submitted;
});
test('editing between two unconfirmed questions retains each original retry identity without an automatic submission',async()=>{
 const app=await consoleApp();await app.select(ids.bidding);await app.loadCurrent(ids.bidding);const originals=[];for(const text of ['Bidding ledger scope','Platform dependency scope']){app.$('question-text').value=text;const submitted=app.submit('question');await flush();const request=app.requests.filter(row=>row.method==='POST').at(-1);assert.match(request.body.requestId,/^[a-f0-9-]{36}$/);originals.push(request);await app.fail(request);await submitted;}assert.notEqual(originals[0].body.requestId,originals[1].body.requestId);app.$('question-text').value=originals[0].body.text;const submitted=app.submit('question');await flush();const retry=app.requests.filter(row=>row.method==='POST').at(-1);assert.equal(retry.body.requestId,originals[0].body.requestId);assert.equal(app.requests.filter(row=>row.method==='POST').length,3);await app.complete(retry,{duplicate:true,queued:0});await app.loadCurrent(ids.bidding);await submitted;
});
test('a late acknowledgement across A to B to A cannot turn the retained original draft into duplicate work',async()=>{
 const app=await consoleApp();await app.select(ids.bidding);await app.loadCurrent(ids.bidding);app.$('question-text').value='Retain this original question across incident switches';const original=app.submit('question');await flush();const first=app.requests.find(row=>row.method==='POST');assert.match(first.body.requestId,/^[a-f0-9-]{36}$/);await app.select(ids.provider);await app.loadCurrent(ids.provider);await app.select(ids.bidding);await app.loadCurrent(ids.bidding);await app.complete(first);await original;assert.equal(app.$('question-text').value,first.body.text);const submitted=app.submit('question');await flush();const retry=app.requests.filter(row=>row.method==='POST').at(-1);assert.equal(retry.body.requestId,first.body.requestId);await app.complete(retry,{duplicate:true,queued:0});await app.loadCurrent(ids.bidding);await submitted;assert.equal(app.$('question-text').value,'');
});
