test('a second old acknowledgement cannot erase a newly typed identical question after the first acknowledgement',async()=>{
 const app=await consoleApp();await app.select(ids.bidding);await app.loadCurrent(ids.bidding);app.$('question-text').value='An intentional identical follow-up';const a=app.submit('question');await flush();const first=app.requests.filter(row=>row.method==='POST').at(-1);assert.match(first.body.requestId,/^[a-f0-9-]{36}$/);const b=app.submit('question');await flush();const second=app.requests.filter(row=>row.method==='POST').at(-1);assert.equal(second.body.requestId,first.body.requestId);await app.complete(first);await app.loadCurrent(ids.bidding);await a;app.$('question-text').value=first.body.text;await app.complete(second,{duplicate:true,queued:0});await app.loadCurrent(ids.bidding);await b;assert.equal(app.$('question-text').value,first.body.text);const c=app.submit('question');await flush();const next=app.requests.filter(row=>row.method==='POST').at(-1);assert.notEqual(next.body.requestId,first.body.requestId);await app.complete(next);await app.loadCurrent(ids.bidding);await c;
});

