test('a lost Teams response reuses its request ID; a confirmed deliberate repeat gets a fresh identity',async()=>{
 const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);const text='update Exact EU retry clue';app.$('teams-text').value=text;let submitted=app.submit('teams');await flush();const first=app.requests.find(r=>r.method==='POST');assert.equal(first.path,'/api/dev/teams/requests');assert.match(first.body.requestId,/^[a-f0-9-]{36}$/);await app.fail(first);await submitted;assert.equal(app.$('teams-text').value,text);assert.match(app.$('teams-feedback').textContent,/retry the same message/);submitted=app.submit('teams');await flush();const retry=app.requests.filter(r=>r.method==='POST').at(-1);assert.equal(retry.body.requestId,first.body.requestId);await app.complete(retry,{duplicate:true});await submitted;assert.equal(app.$('teams-text').value,'');assert.match(app.$('teams-feedback').textContent,/already saved/);assert.match(app.$('teams-feedback').textContent,/did not add another command/);app.$('teams-text').value=text;submitted=app.submit('teams');await flush();const deliberate=app.requests.filter(r=>r.method==='POST').at(-1);assert.notEqual(deliberate.body.requestId,first.body.requestId);await app.complete(deliberate);await submitted;
});
