test('a lost unbound message stays a retry after join confirmation; only a subsequent fresh send can bind it',async()=>{
 const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);app.$('teams-text').value='update Prejoin worker clue';let submitted=app.submit('teams');await flush();const first=app.requests.find(r=>r.method==='POST');await app.fail(first);await submitted;const joining=app.$('teams-join').onclick();await flush();const joinPost=app.requests.filter(r=>r.method==='POST').at(-1);assert.equal(joinPost.body.text,'join '+ids.bidding);assert.notEqual(joinPost.body.requestId,first.body.requestId);await app.complete(joinPost,{commandReceipt:{version:1,id:'c'.repeat(64),incidentId:null,conversationId:joinPost.body.conversationId}});await joining;submitted=app.submit('teams');await flush();const retry=app.requests.filter(r=>r.method==='POST').at(-1);assert.equal(retry.body.requestId,first.body.requestId);await app.complete(retry,{duplicate:true,commandReceipt:{version:1,id:'c'.repeat(64),incidentId:null,conversationId:retry.body.conversationId}});await submitted;assert.equal(app.$('teams-text').value,'update Prejoin worker clue');submitted=app.submit('teams');await flush();const fresh=app.requests.filter(r=>r.method==='POST').at(-1);assert.notEqual(fresh.body.requestId,first.body.requestId);await app.complete(fresh);await submitted;assert.equal(app.$('teams-text').value,'');
});
