test('an older concurrent Teams receipt cannot clear a new same-text intent or retire its retry identity',async()=>{
 const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);const text='update Same intentional text';app.$('teams-text').value=text;const first=app.submit('teams');await flush();const a=app.requests.filter(r=>r.method==='POST').at(-1),second=app.submit('teams');await flush();const b=app.requests.filter(r=>r.method==='POST').at(-1);assert.equal(a.body.requestId,b.body.requestId);await app.complete(a);await first;app.$('teams-text').value=text;const next=app.submit('teams');await flush();const c=app.requests.filter(r=>r.method==='POST').at(-1);assert.notEqual(c.body.requestId,a.body.requestId);await app.complete(b,{duplicate:true});await second;assert.equal(app.$('teams-text').value,text);await app.fail(c);await next;const retrySubmit=app.submit('teams');await flush();const d=app.requests.filter(r=>r.method==='POST').at(-1);assert.equal(d.body.requestId,c.body.requestId);await app.complete(d,{duplicate:true});await retrySubmit;
});
