const teamsObservation=(request,overrides={})=>({version:1,requestId:request.body.requestId,requestedAt:100,observedAt:200,eventId:'c'.repeat(64),ignored:false,commandReceipt:{version:1,id:'c'.repeat(64),incidentId:request.body.expectedIncidentId,conversationId:request.body.conversationId},processing:{state:'pending',leaseExpired:false,error:null},binding:{enabled:true,incidentId:request.body.expectedIncidentId},reply:null,recovery:{active:false,restoreId:null,questionsHeld:false},...overrides});
test('checking an acknowledged Teams instruction sends its original body only to the read route and retains a newer draft',async()=>{const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);app.$('teams-text').value='update Original clue';const sent=app.submit('teams');await flush();const post=app.requests.find(r=>r.method==='POST');await app.complete(post);await sent;app.$('teams-text').value='Unsent newer clue';assert.equal(typeof app.$('teams-request-check').onclick,'function','The console must wire a read-only saved-instruction control');const check=app.$('teams-request-check').onclick();await flush();const read=app.requests.at(-1);assert.equal(read.path,'/api/dev/teams/requests/status');assert.deepEqual(read.body,post.body);await app.complete(read,teamsObservation(read,{processing:{state:'done',leaseExpired:false,error:null},reply:{id:'command:'+'c'.repeat(64),incidentId:null,status:'unknown',text:'Request could not be completed: rejected fictional proposal.',truncated:false,error:null,createdAt:150}}));await check;assert.equal(app.$('teams-text').value,'Unsent newer clue');assert.match(app.$('teams-request-status').textContent,/Command processed/);assert.match(app.$('teams-request-reply').textContent,/could not be completed/);assert.equal(app.requests.filter(r=>r.path==='/api/dev/teams/requests').length,1);});
test('observing an uncertain admission never retires the pending retry identity or clears its draft',async()=>{const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);app.$('teams-text').value='update Original uncertain clue';let sent=app.submit('teams');await flush();const first=app.requests.find(r=>r.method==='POST');await app.fail(first);await sent;assert.equal(typeof app.$('teams-request-check').onclick,'function','The console must wire a read-only saved-instruction control');const check=app.$('teams-request-check').onclick();await flush();const read=app.requests.at(-1);await app.complete(read,teamsObservation(read));await check;assert.equal(app.$('teams-text').value,'update Original uncertain clue');sent=app.submit('teams');await flush();const retry=app.requests.at(-1);assert.equal(retry.path,'/api/dev/teams/requests');assert.equal(retry.body.requestId,first.body.requestId);await app.complete(retry,{duplicate:true});await sent;assert.equal(app.$('teams-text').value,'');});
test('a saved-instruction read can observe the restore hold without enabling commands or clearing the unsent message',async()=>{const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);app.$('teams-text').value='update Queued before hold';const sent=app.submit('teams');await flush();await app.complete(app.requests.at(-1));await sent;app.$('teams-text').value='Unsent during reconciliation';assert.equal(typeof app.$('teams-request-check').onclick,'function','The console must wire a read-only saved-instruction control');const check=app.$('teams-request-check').onclick();await flush();const read=app.requests.at(-1);await app.complete(read,teamsObservation(read,{processing:{state:'discarded',leaseExpired:false,error:'A fresh instruction is required after review'},recovery:{active:true,restoreId:'observed-restore',questionsHeld:false}}));await check;assert.equal(app.$('incident-teams-controls').disabled,true);assert.equal(app.$('teams-request-check').disabled,false);assert.equal(app.$('teams-text').value,'Unsent during reconciliation');assert.match(app.$('teams-request-status').textContent,/discarded/);});
test('a cached saved-instruction observation is historical after status polling discovers a new restore hold',async()=>{const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);app.$('teams-text').value='update Before restore';const sent=app.submit('teams');await flush();await app.complete(app.requests.at(-1));await sent;assert.equal(typeof app.$('teams-request-check').onclick,'function','The console must wire a read-only saved-instruction control');const check=app.$('teams-request-check').onclick();await flush();const read=app.requests.at(-1);await app.complete(read,teamsObservation(read));await check;app.status.recovery={active:true,restoreId:'newer-status-restore',questionsHeld:false};await app.refresh();await app.load(ids.bidding,{recovery:app.status.recovery});assert.equal(app.$('incident-teams-controls').disabled,true);assert.match(app.$('teams-request-status').textContent,/earlier observation.*restore state changed/i);});
test('a late saved-instruction observation cannot present the old pending state as current after a restore hold',async()=>{const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);app.$('teams-text').value='update Before restore';const sent=app.submit('teams');await flush();await app.complete(app.requests.at(-1));await sent;assert.equal(typeof app.$('teams-request-check').onclick,'function','The console must wire a read-only saved-instruction control');const check=app.$('teams-request-check').onclick();await flush();const read=app.requests.at(-1);app.status.recovery={active:true,restoreId:'newer-status-restore',questionsHeld:false};await app.refresh();await app.load(ids.bidding,{recovery:app.status.recovery});await app.complete(read,teamsObservation(read));await check;assert.equal(app.$('incident-teams-controls').disabled,true);assert.match(app.$('teams-request-status').textContent,/Restore state changed while/);});

const savedInstruction=(id,commandId='d'.repeat(64))=>({id:commandId,incidentId:id,sourceAt:90,admittedAt:95,conversationId:'stored-bidding-room',actor:{id:'avery',name:'Avery'},preview:'update Recorded ledger replay fails.',processingState:'done'});
const savedHistory=(id,items)=>({version:1,incidentId:id,observedAt:100,items,nextCursor:null,coverage:{selection:'original-command-binding',pageSize:20,scanned:items.length,inaccessible:0,hasMore:false,completeHistory:false},recovery:{active:false,restoreId:null,questionsHeld:false}});
test('a fresh console loads and opens saved instruction history using GET only while retaining an unsent draft',async()=>{const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);app.$('teams-text').value='Unsent after reload';assert.equal(typeof app.$('teams-history-load').onclick,'function','The console must wire read-only instruction history');const loading=app.$('teams-history-load').onclick();await flush();const request=app.requests.at(-1);assert.equal(request.method,'GET');assert.equal(request.path,'/api/incidents/'+ids.bidding+'/teams-instructions');const item=savedInstruction(ids.bidding);await app.complete(request,savedHistory(ids.bidding,[item]));await loading;assert.equal(app.$('teams-history-items').children.length,1);app.$('teams-history-items').children[0].onclick();await flush();const read=app.requests.at(-1);assert.equal(read.method,'GET');assert.equal(read.path,request.path+'/'+item.id);await app.complete(read,{version:1,requestId:null,commandId:item.id,eventId:item.id,requestedAt:item.sourceAt,admittedAt:item.admittedAt,observedAt:120,ignored:false,commandReceipt:{version:1,id:item.id,incidentId:ids.bidding,conversationId:item.conversationId},processing:{state:'done',leaseExpired:false,error:null},binding:{enabled:true,incidentId:ids.bidding},reply:null,recovery:{active:false,restoreId:null,questionsHeld:false}});assert.equal(app.$('teams-text').value,'Unsent after reload');assert.match(app.$('teams-request-label').textContent,/Selected recorded/);assert.match(app.$('teams-request-status').textContent,/Command processed/);assert.equal(app.requests.filter(r=>r.method==='POST').length,0);});
test('a late history page cannot display another incident or replace its draft',async()=>{const app=await consoleApp();await app.select(ids.bidding);await app.load(ids.bidding);assert.equal(typeof app.$('teams-history-load').onclick,'function','The console must wire read-only instruction history');const loading=app.$('teams-history-load').onclick();await flush();const request=app.requests.at(-1);await app.select(ids.provider);await app.load(ids.provider);app.$('teams-text').value='Unsent provider note';await app.complete(request,savedHistory(ids.bidding,[savedInstruction(ids.bidding)]));await loading;assert.equal(app.$('teams-text').value,'Unsent provider note');assert.ok(!app.$('teams-history-items').innerHTML.includes('Recorded ledger replay'));assert.equal(app.requests.filter(r=>r.method==='POST').length,0);});
test('loading saved history through a restore hold does not enable commands or convert a discarded instruction into a retry',async()=>{const hold={active:true,restoreId:'history-read-hold',questionsHeld:false},app=await consoleApp({recovery:hold});await app.select(ids.bidding);await app.load(ids.bidding,{recovery:hold});app.$('teams-text').value='Unsent held draft';assert.equal(typeof app.$('teams-history-load').onclick,'function','The console must wire read-only instruction history');const loading=app.$('teams-history-load').onclick();await flush();const r=app.requests.at(-1),item={...savedInstruction(ids.bidding),processingState:'discarded'};await app.complete(r,{...savedHistory(ids.bidding,[item]),recovery:hold});await loading;assert.equal(app.$('incident-teams-controls').disabled,true);assert.equal(app.$('teams-history-load').disabled,false);assert.equal(app.$('teams-text').value,'Unsent held draft');assert.ok(app.$('teams-history-items').innerHTML.includes('discarded'));assert.equal(app.requests.filter(r=>r.method==='POST').length,0);});
